import{_ as t,c as a,o as e,ae as i}from"./chunks/framework.Cd-3tpCq.js";const k=JSON.parse('{"title":"Agent Skills","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/build-with-ai/agent-skills.md","filePath":"api/build-with-ai/agent-skills.md"}'),l={name:"api/build-with-ai/agent-skills.md"};function n(o,s,h,r,d,p){return e(),a("div",null,s[0]||(s[0]=[i(`<h1 id="agent-skills" tabindex="-1">Agent Skills <a class="header-anchor" href="#agent-skills" aria-label="Permalink to &quot;Agent Skills&quot;">​</a></h1><p>The <a href="https://github.com/bagisto/agent-skills" target="_blank" rel="noreferrer"><code>bagisto/agent-skills</code></a> repository packages Bagisto&#39;s build-rules as installable <strong>agent skills</strong> — domain-specific instructions that teach an AI agent how to build on and extend the API. This is the fastest way to make an assistant productive on Bagisto: install once, and the agent already knows the flows and the gotchas.</p><h2 id="why-install-them" tabindex="-1">Why install them <a class="header-anchor" href="#why-install-them" aria-label="Permalink to &quot;Why install them&quot;">​</a></h2><p>Without the skills, an agent rediscovers the same lessons every session — often by trial and error against a live store. The skills carry that knowledge up front:</p><ul><li><strong>The correct call sequences.</strong> Catalog → cart → checkout → account are ordered, dependency-aware flows. The skill knows shipping rates need an address first, that a guest cart uses a cart token, and how to merge a guest cart on login.</li><li><strong>The transport gotchas, baked in.</strong> The token model (<code>token</code> is the Bearer, <code>apiToken</code> is legacy), <code>id</code> vs <code>_id</code> vs IRI, the JSON <code>filter:</code> string, <code>sortKey</code>/<code>reverse</code> — the agent applies these instead of guessing.</li><li><strong>Storefront structure.</strong> Which endpoints back the homepage, a category page, a product page, the cart drawer, and the account area — so the generated app matches how the store actually works.</li><li><strong>Parity with the docs.</strong> The skills and this documentation are kept in lockstep, so the agent&#39;s instructions and the reference pages agree.</li></ul><p>The result: less back-and-forth, fewer wrong payloads, and generated code that follows the real API contract on the first pass.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><p><strong>Building an app that consumes the API (storefront / customer app):</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bagisto/agent-skills</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;bagisto-api-shop&quot;</span></span></code></pre></div><p><strong>Building an admin / back-office app:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bagisto/agent-skills</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;bagisto-api-admin&quot;</span></span></code></pre></div><p><strong>Extending the API itself (custom REST/GraphQL endpoints):</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bagisto/agent-skills</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;bagisto-api-develop&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bagisto/agent-skills</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;pest-testing&quot;</span></span></code></pre></div><p><strong>Everything:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bagisto/agent-skills</span></span></code></pre></div><p>Target a specific agent with <code>-a &lt;agent&gt;</code> — <code>claude-code</code>, <code>codex</code>, or <code>antigravity</code>.</p><h2 id="the-skills" tabindex="-1">The skills <a class="header-anchor" href="#the-skills" aria-label="Permalink to &quot;The skills&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Skill</th><th>Use it to</th></tr></thead><tbody><tr><td><code>bagisto-api-shop</code></td><td>Build a storefront / customer app on the Shop API</td></tr><tr><td><code>bagisto-api-admin</code></td><td>Build an admin / back-office app on the Admin API</td></tr><tr><td><code>bagisto-api-develop</code></td><td>Add or extend a REST/GraphQL endpoint in the API package</td></tr><tr><td><code>pest-testing</code></td><td>Write the REST + GraphQL tests that lock both transports</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Grouped skills</p><p>The API skills live under <code>skills/api-platform-development/</code> and share a <code>reference/</code> tree. Installing one pulls the shared reference automatically, so prefer installing the pack (or the grouped skill) over copying a single file.</p></div><h2 id="after-installing" tabindex="-1">After installing <a class="header-anchor" href="#after-installing" aria-label="Permalink to &quot;After installing&quot;">​</a></h2><p>Point the agent at the <a href="/api/build-with-ai/">Build with AI</a> start order — <a href="/api/authentication.html">Authentication</a> and the <a href="/api/workflows/shop/">Storefront</a> overview first, then <a href="/llms.txt"><code>/llms.txt</code></a> to find endpoints, then the <a href="/api/workflows/">Workflows</a> for the call sequence. The skill supplies the rules; the docs supply the exact payloads.</p>`,21)]))}const g=t(l,[["render",n]]);export{k as __pageData,g as default};
